def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def step_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    def pos_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return [x[0], x[1]]
        return None

    def nearest(src, items):
        best = None
        best_d = None
        for it in items:
            p = pos_pair(it)
            if p is None:
                continue
            d = abs(p[0] - src[0]) + abs(p[1] - src[1])
            if best_d is None or d < best_d:
                best_d = d
                best = p
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos_pair(observation.get("self_position")) or [0, 0]
    opp_pos = pos_pair(observation.get("opponent_position")) or self_pos[:]
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = []
        if w and h:
            corners = [[0, 0], [0, h - 1], [w - 1, 0], [w - 1, h - 1]]
        if corners:
            target = max(corners, key=lambda p: abs(p[0] - opp_pos[0]) + abs(p[1] - opp_pos[1]))
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        target = nearest(self_pos, targets)
        if target is None:
            if w and h:
                center = [w // 2, h // 2]
                return step_toward(self_pos, center)
            return step_toward(self_pos, opp_pos)
        return step_toward(self_pos, target)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest(self_pos, resources)
    if target is not None:
        if obs:=observation.get("resource_values"):
            pass
        return step_toward(self_pos, target)

    if env == "resource_collection":
        # If no visible resources, move toward opponent to contest space.
        return step_toward(self_pos, opp_pos)

    # Generic fallback: prefer board center or opponent if dimensions unknown.
    if w and h:
        return step_toward(self_pos, [w // 2, h // 2])
    return step_toward(self_pos, opp_pos)

